import {
  FEATURE_FLAG_DEFINITIONS,
  FEATURE_FLAG_KEYS,
} from "@/config/feature-flags";
import { planAtLeast } from "@/config/plan-limits";
import { ROLE_RANK } from "@/types/member";
import type {
  FeatureFlagKey,
  FeatureFlagSnapshot,
  FlagContext,
} from "@/types/feature-flag";

/**
 * Feature-flag evaluation, shared verbatim by server and client.
 *
 * Server code builds a `FlagContext` from the session and calls `isEnabled()`
 * directly; the dashboard layout serialises `snapshotFlags()` into the client
 * provider so `useFeatureFlag()` answers the same way without a round trip.
 * Both sides must agree — never re-implement a strategy at a call site.
 */
export function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {
  const definition = FEATURE_FLAG_DEFINITIONS[flag];
  if (!definition) return false;

  if (ctx.overrides?.includes(flag)) {
    return true;
  }

  const strategy = definition.strategy;
  switch (strategy.kind) {
    case "off":
      return false;
    case "on":
      return true;
    case "plan":
      return planAtLeast(ctx.plan, strategy.minPlan);
    case "role":
      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];
    case "percentage":
      return bucketOf(flag, ctx) < strategy.percent;
    default:
      return false;
  }
}

/** Evaluates every flag at once, for handoff to the client provider. */
export function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {
  const snapshot = {} as Record<FeatureFlagKey, boolean>;
  for (const key of FEATURE_FLAG_KEYS) {
    snapshot[key] = isEnabled(key, ctx);
  }
  return snapshot;
}

/** Throwing guard for server actions gated behind a flag. */
export class FeatureDisabledError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: FeatureFlagKey) {
    super(`Feature "${flag}" is not enabled for this organization.`);
    this.name = "FeatureDisabledError";
  }
}

export function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {
  if (!isEnabled(flag, ctx)) {
    throw new FeatureDisabledError(flag);
  }
}

/**
 * Deterministic 0–99 bucket for percentage rollouts. Stable per
 * (flag, org, user) so a viewer never sees the feature flicker.
 */
function bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {
  const seed = `${flag}:${ctx.orgId ?? "-"}:${ctx.userId ?? "-"}`;
  let hash = 2_166_136_261;
  for (let i = 0; i < seed.length; i += 1) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16_777_619);
  }
  return Math.abs(hash) % 100;
}
/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  return row ? toOrganization(row) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  // Overrides are a set, not a list to replace: merge so that a patch naming
  // one flag never silently drops the ones switched on before it.
  const settings = {
    ...current.settings,
    ...(patch.settings ?? {}),
    enabledFlagOverrides: [
      ...new Set([
        ...current.settings.enabledFlagOverrides,
        ...(patch.settings?.enabledFlagOverrides ?? []),
      ]),
    ],
  };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}

/** Every rollout strategy plus the org override path. */
import { describe, expect, it } from "vitest";
import { FEATURE_FLAG_KEYS } from "@/config/feature-flags";
import {
  FeatureDisabledError,
  assertEnabled,
  isEnabled,
  snapshotFlags,
} from "@/lib/feature-flags";
import type { FlagContext } from "@/types/feature-flag";
import { ALICE, ORG_A } from "../helpers/factories";

function ctx(overrides: Partial<FlagContext> = {}): FlagContext {
  return { orgId: ORG_A, userId: ALICE, plan: "free", role: "member", ...overrides };
}

describe("lib/feature-flags", () => {
  it("always enables an `on` strategy and never an `off` one", () => {
    expect(isEnabled("command_palette", ctx())).toBe(true);
    expect(isEnabled("command_palette", ctx({ plan: "enterprise", role: "owner" }))).toBe(
      true,
    );
  });

  it("gates a `plan` strategy at the declared minimum plan", () => {
    expect(isEnabled("kanban_board", ctx({ plan: "free" }))).toBe(false);
    expect(isEnabled("kanban_board", ctx({ plan: "starter" }))).toBe(true);
    expect(isEnabled("kanban_board", ctx({ plan: "enterprise" }))).toBe(true);

    expect(isEnabled("activity_feed", ctx({ plan: "starter" }))).toBe(false);
    expect(isEnabled("activity_feed", ctx({ plan: "growth" }))).toBe(true);

    expect(isEnabled("public_projects", ctx({ plan: "growth" }))).toBe(false);
    expect(isEnabled("public_projects", ctx({ plan: "enterprise" }))).toBe(true);
  });

  it("gates a `role` strategy by role rank, not by role equality", () => {
    expect(isEnabled("issue_templates", ctx({ role: "member" }))).toBe(false);
    expect(isEnabled("issue_templates", ctx({ role: "admin" }))).toBe(true);
    expect(isEnabled("issue_templates", ctx({ role: "owner" }))).toBe(true);
    expect(isEnabled("issue_templates", ctx({ role: null }))).toBe(false);
  });

  it("keeps a percentage rollout stable for the same org and user", () => {
    const context = ctx({ plan: "free" });
    const first = isEnabled("ai_issue_summary", context);
    for (let i = 0; i < 20; i += 1) {
      expect(isEnabled("ai_issue_summary", context)).toBe(first);
    }
  });

  it("puts a percentage rollout on both sides of the bucket across users", () => {
    const decisions = new Set<boolean>();
    for (let i = 0; i < 60; i += 1) {
      decisions.add(
        isEnabled(
          "ai_issue_summary",
          ctx({ userId: `01USR${String(i).padStart(21, "0")}` as FlagContext["userId"] }),
        ),
      );
    }
    expect(decisions.size).toBe(2);
  });

  it("lets an org override turn on an overridable flag below its plan", () => {
    expect(isEnabled("kanban_board", ctx({ plan: "free" }))).toBe(false);
    expect(
      isEnabled("kanban_board", ctx({ plan: "free", overrides: ["kanban_board"] })),
    ).toBe(true);
  });

  it("snapshots every known flag as a boolean", () => {
    const snapshot = snapshotFlags(ctx({ plan: "growth", role: "admin" }));
    expect(Object.keys(snapshot).sort()).toEqual([...FEATURE_FLAG_KEYS].sort());
    for (const key of FEATURE_FLAG_KEYS) {
      expect(typeof snapshot[key], key).toBe("boolean");
    }
    expect(snapshot.activity_feed).toBe(true);
    expect(snapshot.public_projects).toBe(false);
  });

  it("agrees with `isEnabled` flag by flag", () => {
    const context = ctx({ plan: "starter", role: "viewer" });
    const snapshot = snapshotFlags(context);
    for (const key of FEATURE_FLAG_KEYS) {
      expect(snapshot[key], key).toBe(isEnabled(key, context));
    }
  });

  it("throws FeatureDisabledError from the guard, naming the flag", () => {
    expect(() => assertEnabled("webhooks", ctx({ plan: "free" }))).toThrow(
      FeatureDisabledError,
    );
    expect(() => assertEnabled("command_palette", ctx())).not.toThrow();

    try {
      assertEnabled("webhooks", ctx({ plan: "free" }));
    } catch (error) {
      expect((error as FeatureDisabledError).flag).toBe("webhooks");
      expect((error as FeatureDisabledError).code).toBe("forbidden");
    }
  });
});
